"use client";

import { type KeyboardEvent, useId, useRef, useState } from "react";

import { ChevronDownIcon } from "@/components/blocks/parts/icons";
import { SegmentedControl } from "@/components/motion/segmented-control";
import { Button } from "@/components/ui/button";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { cn } from "@/lib/utils";

import { BlockFrame } from "../parts/block-frame";
import { RollingText } from "../parts/rolling-text";
import { StatFigure } from "../parts/stat-figure";
import { type ModelGroup, ModelList } from "./model-picker/model-list";
import { EFFORT_LABEL, EFFORT_LEVELS, type Effort, MODELS, modelById } from "./shared/models";

const PRICE = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", minimumFractionDigits: 2, maximumFractionDigits: 2 });

const EFFORTS = EFFORT_LEVELS.map((value) => ({ value, label: EFFORT_LABEL[value] }));

const GROUPS: ModelGroup[] = [
  { label: "Featured", models: MODELS.filter((model) => model.featured) },
  ...[...new Set(MODELS.filter((model) => !model.featured).map((model) => model.provider))].map((provider) => ({
    label: provider,
    models: MODELS.filter((model) => !model.featured && model.provider === provider),
  })),
];

/**
 * A quiet pill that names the model and effort Fern uses, with a note and
 * four figures under it. The pill opens a menu of featured models, an
 * effort setting and every other model by provider. Enter, Space or Down
 * opens it on the current model.
 */
export function ModelPicker({ className }: { className?: string }) {
  const titleId = useId();
  const [modelId, setModelId] = useState("juniper-3");
  const [effort, setEffort] = useState<Effort>("medium");
  const [open, setOpen] = useState(false);
  const list = useRef<HTMLDivElement | null>(null);
  const model = modelById(modelId);

  const onTriggerKey = (event: KeyboardEvent<HTMLButtonElement>) => {
    if (event.key === "ArrowDown") {
      event.preventDefault();
      setOpen(true);
    }
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <div className="flex flex-col gap-4 p-5">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <h2 id={titleId} className="text-base font-semibold">
            Model for the clinic assistant
          </h2>
          <Popover open={open} onOpenChange={setOpen}>
            <PopoverTrigger asChild>
              <Button variant="outline" size="sm" aria-haspopup="listbox" onKeyDown={onTriggerKey}>
                <span aria-hidden="true" className={cn("size-2 rounded-full", model.hue)} />
                <span key={model.id} className="motion-safe:animate-in motion-safe:fade-in">
                  {model.name}
                </span>
                <span className="text-muted-foreground">{EFFORT_LABEL[effort]}</span>
                <ChevronDownIcon aria-hidden="true" className="size-3.5 text-muted-foreground" />
              </Button>
            </PopoverTrigger>
            <PopoverContent
              align="end"
              className="w-[min(22rem,calc(100vw-2rem))]"
              onOpenAutoFocus={(event) => {
                event.preventDefault();
                list.current?.focus();
              }}
            >
              <ModelList
                groups={GROUPS}
                current={modelId}
                listRef={(node) => {
                  list.current = node;
                }}
                onChoose={(id) => {
                  setModelId(id);
                  setOpen(false);
                }}
              />
              <div className="flex items-center justify-between gap-3 border-t border-border px-2 py-2">
                <span className="text-xs font-medium text-muted-foreground">Effort</span>
                <SegmentedControl aria-label="Effort" options={EFFORTS} value={effort} onValueChange={setEffort} />
              </div>
            </PopoverContent>
          </Popover>
        </div>

        <p className="text-sm text-muted-foreground" aria-live="polite">
          {model.name} from {model.provider}. {model.note}
        </p>

        <dl className="grid grid-cols-2 gap-px overflow-hidden rounded-xl border border-border bg-border @xl:grid-cols-4">
          <StatFigure label="Context" value={<RollingText text={`${model.context}K`} />}>
            tokens
          </StatFigure>
          <StatFigure label="Input" value={<RollingText text={PRICE.format(model.input)} />}>
            per million tokens
          </StatFigure>
          <StatFigure label="Output" value={<RollingText text={PRICE.format(model.output)} />}>
            per million tokens
          </StatFigure>
          <StatFigure label="Effort" value={EFFORT_LABEL[effort]}>
            {effort === "high" ? "Slower, more careful" : effort === "low" ? "Fastest replies" : "Balanced"}
          </StatFigure>
        </dl>
        <p className="text-xs text-muted-foreground">Prices are samples for this demo, not quotes.</p>
      </div>
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

/** A warning triangle, from the chosen icon pack. */
export const AlertTriangleIcon = packIcon("alert-triangle");
/** An arrow that points down, from the chosen icon pack. */
export const ArrowDownIcon = packIcon("arrow-up", "rotate-180");
/** An arrow that points left, from the chosen icon pack. */
