import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** Props for a formatted figure whose digits roll. */
export interface RollingTextProps {
  /** A figure that is already formatted, such as "$3,577" or "8.2 min". */
  text: string;
  className?: string;
}

/**
 * Shows a formatted figure and rolls each digit to its new value when the
 * text changes, as a counter does. Signs, separators and units stay still.
 * Each glyph is keyed by its place from the right, so a digit keeps its
 * column when the figure grows. It is for text that already has another
 * spoken source: the rolling columns are hidden from screen readers.
 */
export function RollingText({ text, className }: RollingTextProps) {
  const glyphs = [...text];
  return (
    <span className={cn("inline-flex tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        {glyphs.map((glyph, index) => {
          const place = glyphs.length - 1 - index;
          return glyph >= "0" && glyph <= "9" ? (
            <NumberTicker key={place} value={Number(glyph)} />
          ) : (
            <span key={place} className="whitespace-pre">
              {glyph}
            </span>
          );
        })}
      </span>
    </span>
  );
}

import type { ReactNode } from "react";

import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** A headline figure given as a number, so its digits roll when it changes. */
export interface StatFigureRoll {
  /** The number to show. Round it first when the figure is a whole number. */
  value: number;
  /** A module-level constant, never an inline object: the ticker memoises its formatter on it. */
  format: Intl.NumberFormatOptions;
  /** Text before the number with no space, such as a sign. */
  prefix?: string;
  /** Text after the number with no space, such as "%". */
  suffix?: string;
  /** A word after the number, with a space before it, such as "messages". */
  unit?: string;
}

/** Props for one headline figure. */
export interface StatFigureProps {
  label: string;
  /** The figure as ready text. Leave it out when `roll` is set. */
  value?: ReactNode;
  /** The figure as a number whose digits roll on change. It takes the place of `value`. */
  roll?: StatFigureRoll;
  /** A change figure or a short note under the value. */
  children?: ReactNode;
  className?: string;
}

/** One headline figure with its name and a note. Place it inside a `dl`. */
export function StatFigure({ label, value, roll, children, className }: StatFigureProps) {
  return (
    <div className={cn("flex min-w-0 flex-col gap-1 bg-card px-5 py-4", className)}>
      <dt className="truncate text-sm text-muted-foreground">{label}</dt>
      <dd className="text-2xl font-semibold tracking-tight tabular-nums">
        {roll ? (
          <>
            {roll.prefix}
            <NumberTicker value={roll.value} format={roll.format} />
            {roll.suffix}
            {roll.unit ? ` ${roll.unit}` : null}
          </>
        ) : (
          value
        )}
      </dd>
      {children ? <dd className="flex min-w-0 items-center gap-x-2 overflow-hidden text-xs whitespace-nowrap text-muted-foreground">{children}</dd> : null}
    </div>
  );
}

"use client";

import { type KeyboardEvent, useId, useLayoutEffect, useRef, useState } from "react";

import { CheckIcon } from "@/components/blocks/parts/icons";
import { cn } from "@/lib/utils";

import type { ModelInfo } from "../shared/models";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

/** One titled group of rows in the list. */
export interface ModelGroup {
  label: string;
  models: ModelInfo[];
}

/** Props for the list of models inside the open menu. */
export interface ModelListProps {
  groups: ModelGroup[];
  current: string;
  onChoose: (id: string) => void;
  /** Receives the list element, so the menu can focus it when it opens. */
  listRef: (node: HTMLDivElement | null) => void;
}

/**
 * A listbox of models in titled groups. One highlight sits behind the active
 * row: it glides when the pointer moves it and jumps when the keyboard does.
 * Arrows, Home and End move, a letter jumps to the next model starting with
 * it, and Enter or Space chooses.
 */
export function ModelList({ groups, current, onChoose, listRef }: ModelListProps) {
  const baseId = useId();
  const flat = groups.flatMap((group) => group.models);
  const [active, setActive] = useState(() => Math.max(0, flat.findIndex((model) => model.id === current)));
  const [glide, setGlide] = useState(false);
  const [box, setBox] = useState<{ top: number; height: number } | null>(null);
  const rows = useRef(new Map<number, HTMLDivElement>());
  const optionId = (index: number) => `${baseId}-option-${index}`;

  useLayoutEffect(() => {
    const row = rows.current.get(active);
    if (!row) return;
    setBox({ top: row.offsetTop, height: row.offsetHeight });
    if (!glide) row.scrollIntoView({ block: "nearest" });
  }, [active, glide]);

  const move = (index: number) => {
    setGlide(false);
    setActive((index + flat.length) % flat.length);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const key = event.key;
    if (key === "ArrowDown") move(active + 1);
    else if (key === "ArrowUp") move(active - 1);
    else if (key === "Home") move(0);
    else if (key === "End") move(flat.length - 1);
    else if (key === "Enter" || key === " ") onChoose(flat[active]!.id);
    else if (key.length === 1 && /\w/.test(key)) {
      const letter = key.toLowerCase();
      const order = [...flat.slice(active + 1), ...flat.slice(0, active + 1)];
      const hit = order.find((model) => model.name.toLowerCase().startsWith(letter));
      if (!hit) return;
      move(flat.indexOf(hit));
    } else return;
    event.preventDefault();
  };

  const highlightStyle: VarStyle = { "--y": `${(box?.top ?? 0) / 16}rem`, "--h": `${(box?.height ?? 0) / 16}rem` };
  let index = -1;
  return (
    <div
      ref={listRef}
      role="listbox"
      tabIndex={0}
      aria-label="Models"
      aria-activedescendant={optionId(active)}
      onKeyDown={onKeyDown}
      className="scroll-fade-effect-y scrollbar-none relative max-h-80 overflow-y-auto rounded-md p-1 outline-none focus-visible:ring-2 focus-visible:ring-ring"
    >
      {box ? (
        <span
          aria-hidden="true"
          className={cn("pointer-events-none absolute inset-x-1 top-0 h-(--h) translate-y-(--y) rounded-md bg-accent", glide && "motion-safe:transition-all motion-safe:duration-150 motion-safe:ease-out")}
          style={highlightStyle}
        />
      ) : null}
      {groups.map((group) => (
        <div key={group.label} role="group" aria-labelledby={`${baseId}-${group.label}`}>
          <div id={`${baseId}-${group.label}`} className="relative px-2 pt-2 pb-1 text-xs font-medium text-muted-foreground">
            {group.label}
          </div>
          {group.models.map((model) => {
            index += 1;
            const rowIndex = index;
            const selected = model.id === current;
            return (
              <div
                key={model.id}
                id={optionId(rowIndex)}
                ref={(node) => {
                  if (node) rows.current.set(rowIndex, node);
                  else rows.current.delete(rowIndex);
                }}
                role="option"
                aria-selected={selected}
                onPointerMove={() => {
                  if (rowIndex === active) return;
                  setGlide(true);
                  setActive(rowIndex);
                }}
                onClick={() => onChoose(model.id)}
                className="relative flex cursor-pointer items-start gap-2.5 rounded-md px-2 py-1.5 text-sm"
              >
                <span aria-hidden="true" className={cn("mt-1.5 size-2 shrink-0 rounded-full", model.hue)} />
                <span className="flex min-w-0 flex-1 flex-col">
                  <span className="font-medium">{model.name}</span>
                  <span className="truncate text-xs text-muted-foreground">{model.note}</span>
                </span>
                {selected ? <CheckIcon aria-hidden="true" className="mt-1 size-4 shrink-0" /> : null}
              </div>
            );
          })}
        </div>
      ))}
    </div>
  );
}

/** How hard a model thinks before it answers. */
export type Effort = "low" | "medium" | "high";

/** One invented model the AI blocks offer. Prices are samples, not quotes. */
