  /** The context window, in thousands of tokens. */
  context: number;
  /** Sample price per million input tokens, in dollars. */
  input: number;
  /** Sample price per million output tokens, in dollars. */
  output: number;
  featured: boolean;
  /** A chart hue class, so each model keeps one colour across blocks. */
  hue: string;
}

