/** The effort levels, lowest first. */
export const EFFORT_LEVELS: Effort[] = ["low", "medium", "high"];

/** The words for each effort level. */
export const EFFORT_LABEL = {
  low: "Low",
  medium: "Medium",
  high: "High",
} satisfies Record<Effort, string>;

/** Finds a model by id, falling back to the first. */
export const modelById = (id: string) =>
  MODELS.find((model) => model.id === id) ?? MODELS[0]!;

import type { CSSProperties } from "react";

/**
 * An inline style made only of custom properties, for values known at render
 * such as a point's place in a plot. Classes read them, as `left-(--x)` does.
 */
export type VarStyle = CSSProperties & { [name: `--${string}`]: string | number };
